export const getInvoice = (id: string) => fetch(`/api/v1/invoices/${id}`).then((r) => r.json());
export const createInvoice = (n: Draft) =>
  fetch("/api/v1/invoices", { method: "POST", body: JSON.stringify({ customerId: n.c, amountCents: n.a, dueDate: n.d, currency: "USD", sendReminder: true }) });
export const findCustomers = (q: string) => axios.get("/api/v1/customers?search=" + encodeURIComponent(q));
